  'letture|01|futuro': [
    'Vehuiah ti chiede di puntare su ciò che puoi avviare tu, adesso.',
  ],
  'letture|01|esito': [
    'Vehuiah ti chiede di fare la tua parte per prima, senza aspettare segnali dall\'esterno.',
  ],
  'letture|01|altrui': [
    'Vehuiah ti chiede di chiarire da te che cosa vuoi, senza aspettare l\'altra persona.',
  ],
  'letture|01|decisione': [
    'Vehuiah risponde sì se lo vuoi davvero tu, senza bisogno del permesso di nessuno; se cerchi un\'approvazione, aspetta.',
  ],
  'letture|01|scelta': [
    'Vehuiah ti indica quella che sceglieresti anche senza il permesso di nessuno.',
  ],
  'letture|01|come': [
    'Vehuiah ti indica di fare tu il primo passo, senza aspettare che arrivi dall\'altra parte.',
  ],
  'letture|01|limite': [
    'Vehuiah ti accompagna nel cominciare subito ciò che è tuo: preparare le domande giuste.',
  ],
  'letture|01|cuore_orienta': [
    'Vehuiah ti fa sentire la voglia buona di cominciare.',
  ],
  'letture|01|cuore_attesa': [
    'Vehuiah ti dà il sollievo di muoverti invece di aspettare.',
  ],
  'letture|01|cuore_legami': [
    'Vehuiah ti dà la forza di non restare in attesa.',
  ],
  'letture|01|cuore_scelta': [
    'Vehuiah ti porta la fierezza di una scelta davvero tua.',
  ],
  'letture|01|cuore_limite': [
    'Vehuiah ti dà la forza di fare la tua parte.',
  ],
  'letture|01|intelletto_orienta': [
    'Vehuiah ti mostra che nessuno deve autorizzarti a cominciare.',
  ],
  'letture|01|intelletto_attesa': [
    'Vehuiah ti fa capire che aspettare non è prepararsi.',
  ],
  'letture|01|intelletto_legami': [
    'Vehuiah ti chiarisce che ciò che vuoi non aspetta permessi.',
  ],
  'letture|01|intelletto_scelta': [
    'Vehuiah distingue per te il volere dal cercare un permesso.',
  ],
  'letture|01|intelletto_limite': [
    'Vehuiah ti mostra che la tua parte è prepararti bene.',
  ],
  'letture|01|gesto_orienta': [
    'Scegli una cosa che rimandi in attesa di un via libera e comincia oggi il primo pezzo.',
  ],
  'letture|01|gesto_attesa': [
    'Individua il primo passo che dipende soltanto da te e fallo oggi, prima di qualunque notizia.',
  ],
  'letture|01|gesto_legami': [
    'Scrivi in una riga che cosa vuoi tu in questo rapporto, senza aspettare che lo chiarisca l\'altra persona.',
  ],
  'letture|01|gesto_scelta': [
    'Scrivi quale strada sceglieresti se nessuno dovesse approvarla e tienila come prima candidata, prendendoti il tempo che serve.',
  ],
  'letture|01|gesto_limite': [
    'Metti in agenda oggi il prossimo passo pratico che dipende da te, senza aspettare che qualcuno te lo ricordi.',
  ],
  'letture|02|aperta': [
    'Ieliel volge la tua attenzione ai legami da tenere vivi anche dopo un disaccordo.',
  ],
  'letture|02|futuro': [
    'Ieliel guarda con te ai legami che contano, perché tenerli vivi dipende anche da te.',
  ],
  'letture|02|esito': [
    'Ieliel vuole che la tensione dell\'attesa non allenti i tuoi legami più veri.',
  ],
  'letture|02|altrui': [
    'Ieliel rimette al centro quanto questo legame conta per te e che cosa lo tiene.',
  ],
  'letture|02|decisione': [
    'Ieliel ti risponde sì se puoi farlo restando leale a chi conta; se costa un legame vero, aspetta.',
  ],
  'letture|02|scelta': [
    'Ieliel ti orienta verso quella a cui torneresti anche dopo il primo dubbio.',
  ],
  'letture|02|come': [
    'Ieliel ti chiede di tenere aperto il dialogo anche nei disaccordi, senza voler avere ragione.',
  ],
  'letture|02|limite': [
    'Ieliel ti invita ad appoggiarti alle persone care, invece di portare tutto da te.',
  ],
  'letture|02|cuore_orienta': [
    'Ieliel risveglia in te la fiducia nei legami che tengono.',
  ],
  'letture|02|cuore_attesa': [
    'Ieliel ti fa sentire vicine le persone a cui tieni.',
  ],
  'letture|02|cuore_legami': [
    'Ieliel accoglie in te l\'affetto che regge anche i disaccordi.',
  ],
  'letture|02|cuore_scelta': [
    'Ieliel ti dona la calma di una scelta leale.',
  ],
  'letture|02|cuore_limite': [
    'Ieliel ti scalda col sostegno di chi ti sta vicino.',
  ],
  'letture|02|intelletto_orienta': [
    'Ieliel ti svela che i legami veri reggono ai disaccordi.',
  ],
  'letture|02|intelletto_attesa': [
    'Ieliel ti avverte: l\'attesa non è motivo per chiuderti.',
  ],
  'letture|02|intelletto_legami': [
    'Ieliel ti insegna: un disaccordo non è una rottura.',
  ],
  'letture|02|intelletto_scelta': [
    'Ieliel ti chiarisce che scegliere non significa rompere un legame.',
  ],
  'letture|02|intelletto_limite': [
    'Ieliel ti ricorda che farti aiutare rafforza un legame.',
  ],
  'letture|02|gesto_orienta': [
    'Pensa a una persona che conta per te e dedicale oggi un gesto di presenza, senza aspettare un\'occasione.',
  ],
  'letture|02|gesto_attesa': [
    'Mentre aspetti, passa del tempo con una persona che ti è cara e parlale anche d\'altro, non soltanto dell\'attesa.',
  ],
  'letture|02|gesto_legami': [
    'Scrivi in una riga che cosa conta per te in questo legame, al di là di ogni disaccordo.',
  ],
  'letture|02|gesto_scelta': [
    'Immagina un primo giorno difficile su ciascuna strada e chiediti a quale torneresti comunque, senza fretta.',
  ],
  'letture|02|gesto_limite': [
    'Chiedi a una persona di fiducia di aiutarti a preparare le domande per chi ti segue.',
  ],
  'letture|03|aperta': [
    'Sitael ti chiede di aggiungere oggi un pezzo a ciò che costruisci negli anni.',
  ],
  'letture|03|futuro': [
    'Sitael punta su ciò che costruisci con pazienza e sulle tue promesse mantenute.',
  ],
  'letture|03|esito': [
    'Sitael ti esorta a costruire con pazienza mentre aspetti: ciò che vale cresce piano.',
  ],
  'letture|03|altrui': [
    'Sitael ti insegna a pesare ciò che dura, non le parole di un giorno.',
  ],
  'letture|03|decisione': [
    'Sitael approva il sì se è una parola che puoi mantenere negli anni; altrimenti aspetta.',
  ],
  'letture|03|scelta': [
    'Sitael ti consiglia quella che puoi costruire negli anni, non la più rapida.',
  ],
  'letture|03|come': [
    'Sitael ti mostra la via della parola mantenuta: prometti poco e fai ciò che dici.',
  ],
  'letture|03|limite': [
    'Sitael regge con te i tempi lunghi, nella costanza degli impegni che dipendono da te.',
  ],
  'letture|03|cuore_orienta': [
    'Sitael nutre in te la fierezza quieta di chi costruisce.',
  ],
  'letture|03|cuore_attesa': [
    'Sitael ti concede la calma di chi costruisce con pazienza.',
  ],
  'letture|03|cuore_legami': [
    'Sitael ti fa sentire il valore della parola mantenuta.',
  ],
  'letture|03|cuore_scelta': [
    'Sitael ti infonde la serenità di un impegno che regge.',
  ],
  'letture|03|cuore_limite': [
    'Sitael accende in te la tenuta per i tempi lunghi.',
  ],
  'letture|03|intelletto_orienta': [
    'Sitael ti rivela che ciò che dura cresce piano.',
  ],
  'letture|03|intelletto_attesa': [
    'Sitael ti ricorda: un singolo esito non misura un cammino.',
  ],
  'letture|03|intelletto_legami': [
    'Sitael ti spiega che la fiducia cresce coi gesti ripetuti.',
  ],
  'letture|03|intelletto_scelta': [
    'Sitael separa per te l\'intenzione dalla promessa che regge.',
  ],
  'letture|03|intelletto_limite': [
    'Sitael ti dimostra che la costanza vale più della fretta.',
  ],
  'letture|03|gesto_orienta': [
    'Riprendi un tuo impegno di lunga durata e aggiungici oggi un piccolo pezzo, anche di dieci minuti.',
  ],
  'letture|03|gesto_attesa': [
    'Ogni giorno di questa settimana mantieni un piccolo impegno che hai preso, qualunque notizia arrivi.',
  ],
  'letture|03|gesto_legami': [
    'Pensa a una parola che hai dato in questo rapporto e verifica in silenzio se la stai mantenendo.',
  ],
  'letture|03|gesto_scelta': [
    'Immagina ciascuna strada fra qualche anno e scrivi quale ti senti di mantenere davvero, senza fretta.',
  ],
  'letture|03|gesto_limite': [
    'Raccogli in un\'unica cartella documenti e scadenze che ti riguardano, poi aggiornala ogni settimana con costanza.',
  ],
  'letture|04|aperta': [
    'Elemiah ti aiuta a separare l\'ostacolo reale dall\'agitazione che senti dentro.',
  ],
  'letture|04|futuro': [
    'Elemiah tiene il tuo sguardo su ciò che è reale, non sulle tue paure.',
  ],
  'letture|04|esito': [
    'Elemiah ti invita ad affrontare ciò che è reale, senza nutrire l\'agitazione dell\'attesa.',
  ],
  'letture|04|altrui': [
    'Elemiah separa con te i fatti che vedi dalle paure che senti.',
  ],
  'letture|04|decisione': [
    'Elemiah ti dice sì se a frenarti è soltanto l\'agitazione; se c\'è un ostacolo reale, aspetta.',
  ],
  'letture|04|scelta': [
    'Elemiah ti fa scegliere quella che resta giusta quando l\'agitazione si calma.',
  ],
  'letture|04|come': [
    'Elemiah ti porta a nominare il punto concreto, lasciando fuori la tensione che senti dentro.',
  ],
  'letture|04|limite': [
    'Elemiah ti accompagna nel guardare con lucidità ciò che sai davvero, senza farti travolgere dall\'agitazione.',
  ],
  'letture|04|cuore_orienta': [
    'Elemiah ti rende la fiducia nel tuo discernimento.',
  ],
  'letture|04|cuore_attesa': [
    'Elemiah ti concede di sentire l\'ansia senza crederle tutto.',
  ],
  'letture|04|cuore_legami': [
    'Elemiah ti lascia ascoltare l\'intuito, non il tumulto.',
  ],
  'letture|04|cuore_scelta': [
    'Elemiah ti trasmette la fermezza di chi vede chiaro.',
  ],
  'letture|04|cuore_limite': [
    'Elemiah accoglie la tua paura senza lasciarle il comando.',
  ],
  'letture|04|intelletto_orienta': [
    'Elemiah ti chiarisce che l\'agitazione non è l\'ostacolo vero.',
  ],
  'letture|04|intelletto_attesa': [
    'Elemiah ti mostra: ciò che passa col riposo era agitazione.',
  ],
  'letture|04|intelletto_legami': [
    'Elemiah separa per te i fatti visti dalle paure immaginate.',
  ],
  'letture|04|intelletto_scelta': [
    'Elemiah distingue il rischio reale dalla paura che ti frena.',
  ],
  'letture|04|intelletto_limite': [
    'Elemiah ti insegna che i fatti calmano più delle ipotesi.',
  ],
  'letture|04|gesto_orienta': [
    'Dividi un foglio in due colonne e scrivi a sinistra ciò che ti frena davvero, a destra le paure.',
  ],
  'letture|04|gesto_attesa': [
    'Quando l\'agitazione sale, chiediti che cosa è cambiato davvero da ieri e lascia andare il resto.',
  ],
  'letture|04|gesto_legami': [
    'Annota tre gesti concreti che hai visto in questo rapporto e separali da ciò che hai soltanto immaginato.',
  ],
  'letture|04|gesto_scelta': [
    'Per ciascuna strada scrivi gli ostacoli reali e quelli che senti soltanto dentro; rileggi la lista fra qualche giorno.',
  ],
  'letture|04|gesto_limite': [
    'Separa i fatti che conosci dalle ipotesi che ti agitano e trasforma queste in domande per chi ti segue.',
  ],
  'letture|05|aperta': [
    'Mahasiah ti propone di restare in pace oggi, senza cedere su ciò che conta.',
  ],
  'letture|05|futuro': [
    'Mahasiah ti affida la tua pace, da custodire senza cedere su ciò che conta.',
  ],
  'letture|05|esito': [
    'Mahasiah ti insegna ad attendere in pace, senza mollare ciò che conta per te.',
  ],
  'letture|05|altrui': [
    'Mahasiah ti ricorda di tenere la tua serenità senza mettere da parte ciò che sei.',
  ],
  'letture|05|decisione': [
    'Mahasiah concede il sì se lo scegli in pace; se è cedere per quieto vivere, no.',
  ],
  'letture|05|scelta': [
    'Mahasiah sceglie con te quella che ti dà pace senza farti cedere sull\'essenziale.',
  ],
  'letture|05|come': [
    'Mahasiah ti consiglia la calma nel tono e la fermezza su ciò che conta.',
  ],
  'letture|05|limite': [
    'Mahasiah ti affianca nel chiedere con calma e fermezza ciò che ancora non capisci.',
  ],
  'letture|05|cuore_orienta': [
    'Mahasiah ti scalda con una pace che non cede.',
  ],
  'letture|05|cuore_attesa': [
    'Mahasiah ti dà una calma che non è rassegnazione.',
  ],
  'letture|05|cuore_legami': [
    'Mahasiah ti lascia la pace di chi non si annulla.',
  ],
  'letture|05|cuore_scelta': [
    'Mahasiah ti consegna la quiete di una scelta senza resa.',
  ],
  'letture|05|cuore_limite': [
    'Mahasiah ti accoglie in una quiete più forte della paura.',
  ],
  'letture|05|intelletto_orienta': [
    'Mahasiah ti fa capire che la pace non è resa.',
  ],
  'letture|05|intelletto_attesa': [
    'Mahasiah distingue per te l\'attesa serena da quella rassegnata.',
  ],
  'letture|05|intelletto_legami': [
    'Mahasiah ti chiarisce che fare pace non è dare ragione.',
  ],
  'letture|05|intelletto_scelta': [
    'Mahasiah ti avverte: un sì per quieto vivere è cedere.',
  ],
  'letture|05|intelletto_limite': [
    'Mahasiah ti fa notare: la calma rende chiare le domande.',
  ],
  'letture|05|gesto_orienta': [
    'Scrivi su un biglietto la cosa su cui oggi non cedi e tienilo con te: dilla con calma, se serve.',
  ],
  'letture|05|gesto_attesa': [
    'Quando l\'attesa ti agita, respira lentamente e riprendi con calma la cosa che stavi facendo.',
  ],
  'letture|05|gesto_legami': [
    'Annota la cosa su cui in questo rapporto non cedi e una su cui puoi venire incontro.',
  ],
  'letture|05|gesto_scelta': [
    'Chiediti con calma quale strada puoi percorrere senza cedere sull\'essenziale e lascia maturare la risposta per qualche giorno.',
  ],
  'letture|05|gesto_limite': [
    'Prepara con calma le domande per chi ti segue e non lasciar cadere quella che ti preme di più.',
  ],
  'letture|06|aperta': [
    'Lelahel ti invita a usare le tue capacità per chiarire, non per farti ammirare.',
  ],
  'letture|06|futuro': [
    'Lelahel mette al centro le tue capacità, usate per fare chiarezza e non per brillare.',
  ],
  'letture|06|esito': [
    'Lelahel ti suggerisce di usare le tue capacità per chiarire, non per impressionare.',
  ],
  'letture|06|altrui': [
    'Lelahel porta chiarezza nel tuo sguardo, senza lasciarti abbagliare da ciò che speri.',
  ],
  'letture|06|decisione': [
    'Lelahel ti risponde sì se la scelta porta chiarezza; se serve a fare bella figura, no.',
  ],
  'letture|06|scelta': [
    'Lelahel ti porta verso quella dove le tue capacità servono davvero, non dove brillano.',
  ],
  'letture|06|come': [
    'Lelahel ti chiede di usare le tue doti per chiarire, non per avere l\'ultima parola.',
  ],
  'letture|06|limite': [
    'Lelahel ti guida a cercare chiarezza, senza farti abbagliare da ciò che leggi in giro.',
  ],
  'letture|06|cuore_orienta': [
    'Lelahel accende la gioia limpida di ciò che sai fare.',
  ],
  'letture|06|cuore_attesa': [
    'Lelahel ti concede la fiducia in ciò che sai fare.',
  ],
  'letture|06|cuore_legami': [
    'Lelahel ti apre alla gioia di farti capire, non ammirare.',
  ],
  'letture|06|cuore_scelta': [
    'Lelahel ti fa sentire la gioia di una scelta limpida.',
  ],
  'letture|06|cuore_limite': [
    'Lelahel ti porta il sollievo di capire con chiarezza.',
  ],
  'letture|06|intelletto_orienta': [
    'Lelahel ti fa capire che un talento vale quando chiarisce.',
  ],
  'letture|06|intelletto_attesa': [
    'Lelahel ti mostra che la chiarezza pesa più dell\'effetto.',
  ],
  'letture|06|intelletto_legami': [
    'Lelahel distingue per te il farti capire dal farti ammirare.',
  ],
  'letture|06|intelletto_scelta': [
    'Lelahel ti fa vedere la differenza fra servire e brillare.',
  ],
  'letture|06|intelletto_limite': [
    'Lelahel ti chiarisce che capire bene viene prima di decidere.',
  ],
  'letture|06|gesto_orienta': [
    'Offri oggi a una persona un po\' del tuo tempo su ciò che sai fare, senza chiedere niente in cambio.',
  ],
  'letture|06|gesto_attesa': [
    'Spiega a voce alta, in parole semplici, a che punto sei e che cosa dipende ancora da te.',
  ],
  'letture|06|gesto_legami': [
    'Prima di parlare in questo rapporto chiediti se vuoi chiarire qualcosa o soltanto farti valere.',
  ],
  'letture|06|gesto_scelta': [
    'Scrivi ciascuna strada in tre frasi semplici, come a chi non ne sa nulla; rileggile nei giorni seguenti.',
  ],
  'letture|06|gesto_limite': [
    'Chiedi a chi ti segue di spiegarti ciò che non è chiaro e riscrivilo con parole tue.',
  ],
  'letture|07|aperta': [
    'Achaiah rallenta il tuo sguardo, perché oggi conta osservare più che concludere.',
  ],
  'letture|07|futuro': [
    'Achaiah guarda a ciò che puoi imparare adesso, osservando con pazienza.',
  ],
  'letture|07|esito': [
    'Achaiah ti fa osservare come evolvono le cose, senza concludere prima del tempo.',
  ],
  'letture|07|altrui': [
    'Achaiah osserva con te, senza trarre conclusioni da un gesto isolato.',
  ],
  'letture|07|decisione': [
    'Achaiah accoglie il sì se hai osservato abbastanza da conoscere ciò che scegli; se è un\'impressione, aspetta.',
  ],
  'letture|07|scelta': [
    'Achaiah preferisce con te quella che regge a uno sguardo paziente, non alla prima occhiata.',
  ],
  'letture|07|come': [
    'Achaiah ti raccomanda di ascoltare e osservare a lungo prima di intervenire.',
  ],
  'letture|07|limite': [
    'Achaiah resta con te nell\'osservare come vanno le cose, senza trarre conclusioni affrettate.',
  ],
  'letture|07|cuore_orienta': [
    'Achaiah ti restituisce la meraviglia di chi resta a guardare.',
  ],
  'letture|07|cuore_attesa': [
    'Achaiah ti dona una pazienza curiosa di ciò che viene.',
  ],
  'letture|07|cuore_legami': [
    'Achaiah coltiva in te una curiosità paziente verso l\'altra persona.',
  ],
  'letture|07|cuore_scelta': [
    'Achaiah ti concede di non decidere in fretta.',
  ],
  'letture|07|cuore_limite': [
    'Achaiah ti concede di non sapere ancora tutto, senza ansia.',
  ],
  'letture|07|intelletto_orienta': [
    'Achaiah ti fa capire che osservare è già imparare.',
  ],
  'letture|07|intelletto_attesa': [
    'Achaiah distingue per te l\'attesa vuota dall\'osservazione paziente.',
  ],
  'letture|07|intelletto_legami': [
    'Achaiah ti avverte: una persona si conosce nel tempo.',
  ],
  'letture|07|intelletto_scelta': [
    'Achaiah ti fa capire che la prima impressione non basta.',
  ],
  'letture|07|intelletto_limite': [
    'Achaiah ti ricorda che capire richiede tempo, non conclusioni rapide.',
  ],
  'letture|07|gesto_orienta': [
    'Riprendi una cosa che credi di conoscere e annota tre dettagli che finora ti erano sfuggiti.',
  ],
  'letture|07|gesto_attesa': [
    'Tieni per una settimana un diario di poche righe su ciò che osservi, senza trarne conclusioni.',
  ],
  'letture|07|gesto_legami': [
    'Per qualche giorno ascolta più di quanto parli in questo rapporto e annota ciò che impari.',
  ],
  'letture|07|gesto_scelta': [
    'Raccogli per ciascuna strada un\'informazione che ancora ti manca e aspetta di averle tutte prima di scegliere.',
  ],
  'letture|07|gesto_limite': [
    'Annota ogni giorno in poche righe ciò che osservi e porta queste note a chi ti segue.',
  ],
  'letture|08|aperta': [
    'Cahethel volge il tuo sguardo a ciò che hai e alla fatica che è costato.',
  ],
  'letture|08|futuro': [
    'Cahethel parte con te da ciò che hai già, con gratitudine concreta.',
  ],
  'letture|08|esito': [
    'Cahethel vuole che tu dia valore all\'impegno che hai già messo, mentre aspetti.',
  ],
  'letture|08|altrui': [
    'Cahethel ti fa riconoscere con gratitudine i gesti concreti che hai dato e ricevuto.',
  ],
  'letture|08|decisione': [
    'Cahethel dà il sì se conosci la fatica che costa e l\'accetti; se vuoi soltanto il frutto, aspetta.',
  ],
  'letture|08|scelta': [
    'Cahethel ti guida verso quella in cui la fatica vale il frutto che porta.',
  ],
  'letture|08|come': [
    'Cahethel ti propone di riconoscere con gesti concreti la fatica che fa l\'altra persona.',
  ],
  'letture|08|limite': [
