  'letture|24|aperta': [
    'Haheuiah ti invita a scegliere che cosa lasci entrare nelle tue giornate.',
  ],
  'letture|24|futuro': [
    'Haheuiah ti rimette in mano ciò che dipende da te: che cosa lasci entrare.',
  ],
  'letture|24|esito': [
    'Haheuiah ti chiede di mettere un confine all\'attesa, perché non occupi tutte le tue giornate.',
  ],
  'letture|24|altrui': [
