  'letture|24|cuore_orienta': [
    'Haheuiah ti regala la quiete di uno spazio tutto tuo.',
  ],
  'letture|24|cuore_attesa': [
    'Haheuiah ti restituisce il respiro che l\'attesa ti toglie.',
