  'letture|32|aperta': [
    'Vasariah ti consiglia oggi di misurare prima di giudicare, distinguendo l\'errore dalla persona.',
  ],
  'letture|32|futuro': [
    'Vasariah ti affida ciò che dipende da te: giudicare con equità, senza durezza.',
  ],
  'letture|32|esito': [
    'Vasariah ti domanda di attendere misurando i fatti prima di giudicarli, con clemenza.',
  ],
  'letture|32|altrui': [
    'Vasariah ti propone uno sguardo giusto e clemente: un gesto non è tutta una persona.',
  ],
  'letture|32|decisione': [
    'Vasariah dice sì se la scelta è giusta verso tutti e verso di te; se punisce qualcuno, aspetta.',
  ],
  'letture|32|scelta': [
    'Vasariah raccomanda quella che è giusta senza durezza, verso gli altri e verso di te.',
  ],
  'letture|32|come': [
    'Vasariah ti consiglia di parlare dei gesti, mai di ciò che l\'altra persona è.',
  ],
  'letture|32|limite': [
    'Vasariah ti sta accanto mentre guardi i fatti con giustizia, senza condannarti.',
  ],
  'letture|32|cuore_orienta': [
    'Vasariah ti trasmette la mitezza di chi giudica senza durezza.',
  ],
  'letture|32|cuore_attesa': [
    'Vasariah ti consente l\'indulgenza verso le tue paure.',
