  'letture|33|limite': [
    'Iehuiah ti aiuta a presentarti come persona con domande tue, non come un fascicolo.',
  ],
  'letture|33|cuore_orienta': [
    'Iehuiah ti fa sentire lo spazio tuo dentro ogni ruolo.',
  ],
  'letture|33|cuore_attesa': [
    'Iehuiah ti dona la serenità di valere oltre il risultato.',
  ],
  'letture|33|cuore_legami': [
    'Iehuiah ti porta la libertà di essere te nel legame.',
  ],
  'letture|33|cuore_scelta': [
    'Iehuiah ti infonde la fiducia di scegliere restando chi sei.',
