  'letture|36|intelletto_attesa': [
    'Menadel ti fa capire che l\'impegno non dipende dall\'esito.',
  ],
  'letture|36|intelletto_legami': [
    'Menadel ti mostra che un legame si impara vivendolo.',
  ],
  'letture|36|intelletto_scelta': [
    'Menadel ti insegna che restare per paura non è imparare.',
  ],
  'letture|36|intelletto_limite': [
    'Menadel ricorda che la tua parte è la costanza quotidiana.',
  ],
  'letture|36|gesto_orienta': [
    'Scegli un piccolo compito di oggi e fallo con più cura del solito, chiedendoti che cosa ti insegna.',
  ],
  'letture|36|gesto_attesa': [
    'Scrivi stasera che cosa hai imparato oggi da ciò che fai ogni giorno, mentre aspetti.',
