  'letture|45|cuore_attesa': [
    'Sealiah ti lascia sentire fiducia in ciò che matura piano.',
  ],
  'letture|45|cuore_legami': [
    'Sealiah ti porta la calma di chi procede adagio.',
  ],
  'letture|45|cuore_scelta': [
    'Sealiah ti concede la calma di non dover correre.',
  ],
  'letture|45|cuore_limite': [
    'Sealiah ti dona la pazienza dei piccoli passi.',
  ],
  'letture|45|intelletto_orienta': [
    'Sealiah ti sottolinea che lento non vuol dire fermo.',
  ],
  'letture|45|intelletto_attesa': [
    'Sealiah ti insegna che pretendere subito rallenta ciò che riparte.',
  ],
  'letture|45|intelletto_legami': [
    'Sealiah ti ricorda che ogni legame ha tempi suoi.',
