  'letture|51|gesto_legami': [
    'Osserva per una settimana che cosa accende in te vicinanza o tensione verso l\'altra persona e annotalo.',
  ],
  'letture|51|gesto_scelta': [
    'Raccogli su ciascuna strada tre informazioni concrete che ancora ti mancano, prima di metterci le mani.',
  ],
  'letture|51|gesto_limite': [
    'Scrivi ciò che non ti è chiaro e chiedi a chi ti segue di spiegartelo passo per passo.',
  ],
  'letture|52|aperta': [
    'Imamiah ti propone di guardare un tuo sbaglio con mitezza, poi di ripartire dai fatti.',
  ],
  'letture|52|futuro': [
    'Imamiah ti spinge a puntare sui passi che puoi fare adesso, senza rimproverarti per ieri.',
  ],
  'letture|52|esito': [
    'Imamiah ti sprona a correggere ciò che ancora puoi, senza condannarti per il resto.',
  ],
  'letture|52|altrui': [
    'Imamiah ti aiuta a guardare la tua parte nel legame senza condannarti né condannare.',
  ],
  'letture|52|decisione': [
    'Imamiah ammette il sì se ti concedi di poter sbagliare senza condanna; se decide la paura, aspetta.',
  ],
  'letture|52|scelta': [
    'Imamiah sceglie con te quella che prenderesti se la paura di sbagliare non ti chiudesse.',
  ],
  'letture|52|come': [
    'Imamiah propone di guardare gli errori, tuoi e altrui, senza farne una condanna.',
  ],
  'letture|52|limite': [
    'Imamiah ti guida fuori dai pensieri chiusi, verso i passi concreti che ti spettano.',
  ],
  'letture|52|cuore_orienta': [
    'Imamiah ammorbidisce in te lo sguardo sui tuoi sbagli.',
  ],
  'letture|52|cuore_attesa': [
    'Imamiah scioglie in te il rimprovero che non serve.',
  ],
  'letture|52|cuore_legami': [
    'Imamiah ti infonde l\'umiltà di ammettere senza umiliarti.',
  ],
  'letture|52|cuore_scelta': [
    'Imamiah ti infonde la fiducia di poter sbagliare senza crollare.',
  ],
  'letture|52|cuore_limite': [
    'Imamiah ti concede una tenerezza senza rimproveri.',
  ],
  'letture|52|intelletto_orienta': [
    'Imamiah ti dimostra che ammettere un errore è già riparare.',
  ],
  'letture|52|intelletto_attesa': [
    'Imamiah ti ricorda che uno sbaglio non è una condanna.',
  ],
  'letture|52|intelletto_legami': [
    'Imamiah distingue per te la tua parte dalla colpa intera.',
  ],
  'letture|52|intelletto_scelta': [
    'Imamiah ti rende chiaro che temere l\'errore non è prudenza.',
  ],
  'letture|52|intelletto_limite': [
    'Imamiah ti spiega che rimproverarti non ti aiuta a decidere.',
  ],
  'letture|52|gesto_orienta': [
    'Scrivi un tuo errore recente e accanto un fatto concreto con cui ripararlo questa settimana.',
  ],
  'letture|52|gesto_attesa': [
    'Sostituisci ogni rimprovero che ti fai su ciò che aspetti con un passo concreto, scritto in una riga.',
  ],
  'letture|52|gesto_legami': [
    'Metti in una riga la tua parte in questo rapporto senza accusarti né giustificarti, poi tienila per te.',
  ],
  'letture|52|gesto_scelta': [
    'Scrivi quale errore temi in ciascuna strada e accanto come lo affronteresti, senza farne una condanna.',
  ],
  'letture|52|gesto_limite': [
    'Lascia da parte i rimproveri che ti fai e scrivi domande precise per chi ti segue.',
  ],
  'letture|53|aperta': [
    'Nanael oggi ti chiede di essere, in silenzio, una persona su cui si può contare.',
  ],
  'letture|53|futuro': [
    'Nanael punta sull\'impegno silenzioso e paziente che fa di te una persona affidabile.',
  ],
  'letture|53|esito': [
    'Nanael ti incoraggia a continuare con pazienza e in silenzio, senza cercare conferme.',
  ],
  'letture|53|altrui': [
    'Nanael ti propone pazienza e silenzio, restando tu una persona su cui contare.',
  ],
  'letture|53|decisione': [
    'Nanael accoglie il sì se puoi sostenere questa scelta nel tempo lungo, anche quando nessuno applaude; altrimenti aspetta.',
  ],
  'letture|53|scelta': [
    'Nanael privilegia quella in cui puoi essere affidabile a lungo, anche lontano dagli sguardi.',
  ],
  'letture|53|come': [
    'Nanael ti consiglia di essere una presenza affidabile: poche parole, fatti costanti.',
  ],
  'letture|53|limite': [
    'Nanael ti sostiene nella pazienza silenziosa, mentre impari con calma ciò che serve sapere.',
  ],
  'letture|53|cuore_orienta': [
    'Nanael custodisce in te la pace del silenzio.',
  ],
  'letture|53|cuore_attesa': [
    'Nanael ti infonde la pazienza serena del tempo lungo.',
  ],
  'letture|53|cuore_legami': [
    'Nanael ti fa sentire il valore di esserci senza clamore.',
  ],
  'letture|53|cuore_scelta': [
    'Nanael ti regala la serenità di chi non cerca applausi.',
  ],
  'letture|53|cuore_limite': [
    'Nanael ti fa sentire la calma di chi sa attendere.',
  ],
  'letture|53|intelletto_orienta': [
    'Nanael ti rende chiaro che l\'affidabilità vale più della popolarità.',
  ],
  'letture|53|intelletto_attesa': [
    'Nanael ti insegna che ciò che è profondo chiede tempo.',
  ],
  'letture|53|intelletto_legami': [
    'Nanael ti avverte che la fiducia nasce da fatti silenziosi.',
  ],
  'letture|53|intelletto_scelta': [
    'Nanael ti ricorda che il clamore non misura il valore.',
  ],
  'letture|53|intelletto_limite': [
    'Nanael ti rende chiaro che capire chiede tempo e domande.',
  ],
  'letture|53|gesto_orienta': [
    'Mantieni oggi un tuo piccolo impegno con qualcuno, in silenzio e senza farlo notare.',
  ],
  'letture|53|gesto_attesa': [
    'Dedica ogni giorno un tuo tempo silenzioso a ciò che aspetti, senza controllare di continuo le notizie.',
  ],
  'letture|53|gesto_legami': [
    'Fai una cosa concreta su cui chi ti sta vicino possa contare questa settimana, senza farne parola.',
  ],
  'letture|53|gesto_scelta': [
    'Dedica alla tua scelta qualche ora di silenzio e studio, prima di chiedere pareri o parlarne.',
  ],
  'letture|53|gesto_limite': [
    'Prenditi un\'ora di silenzio per rileggere ciò che sai già e scrivere le domande per chi ti segue.',
  ],
  'letture|54|aperta': [
    'Nithael ti orienta verso la bellezza che dura e verso il piacere di mostrarla.',
  ],
  'letture|54|futuro': [
    'Nithael ti chiede di puntare su ciò che dura, non su ciò che passa.',
  ],
  'letture|54|esito': [
    'Nithael ti ricorda di non perdere il bello di questo tempo mentre aspetti.',
  ],
  'letture|54|altrui': [
    'Nithael ti incoraggia a riconoscere ciò che di bello resta in te, comunque vada.',
  ],
  'letture|54|decisione': [
    'Nithael sostiene il sì se la scelta ti lascia qualcosa di bello e duraturo; altrimenti aspetta.',
  ],
  'letture|54|scelta': [
    'Nithael ti mostra quella che lascia qualcosa di bello anche oltre te.',
  ],
  'letture|54|come': [
    'Nithael ti fa partire dal bello che c\'è fra te e l\'altra persona.',
  ],
  'letture|54|limite': [
    'Nithael ti fa tenere presente il bello che hai, mentre chiedi a chi sa.',
  ],
  'letture|54|cuore_orienta': [
    'Nithael ti fa provare meraviglia per le cose belle.',
  ],
  'letture|54|cuore_attesa': [
    'Nithael ti porta lo stupore per ciò che già c\'è.',
  ],
  'letture|54|cuore_legami': [
    'Nithael ti dà la gioia di cogliere il bello altrui.',
  ],
  'letture|54|cuore_scelta': [
    'Nithael accende in te il desiderio di qualcosa che resti.',
  ],
  'letture|54|cuore_limite': [
    'Nithael ti conforta col bello che resta, anche adesso.',
  ],
  'letture|54|intelletto_orienta': [
    'Nithael ti rivela che mostrare il bello è generosità.',
  ],
  'letture|54|intelletto_attesa': [
    'Nithael ti ricorda che ciò che dura non ha fretta.',
  ],
  'letture|54|intelletto_legami': [
    'Nithael ti spiega che vedere il bello non è idealizzare.',
  ],
  'letture|54|intelletto_scelta': [
    'Nithael separa per te l\'effimero da ciò che dura.',
  ],
  'letture|54|intelletto_limite': [
    'Nithael ricorda che il bello non sparisce nei momenti duri.',
  ],
  'letture|54|gesto_orienta': [
    'Nota oggi una cosa bella che altri non guardano e mostrala a una persona cara.',
  ],
  'letture|54|gesto_attesa': [
    'Elenca tre cose belle che hai già costruito per ciò che aspetti e mostrane una a qualcuno.',
  ],
  'letture|54|gesto_legami': [
    'Ripensa a un tuo ricordo bello di questo legame e scrivilo con cura in poche righe, per custodirlo.',
  ],
  'letture|54|gesto_scelta': [
    'Immagina di raccontare ciascuna strada fra molti anni e nota quale storia ti sembra più bella.',
  ],
  'letture|54|gesto_limite': [
    'Tieni accanto una cosa bella che ti ricordi chi sei mentre prepari le domande per chi ti segue.',
  ],
  'letture|55|aperta': [
    'Mebahiah ti orienta verso la coerenza fra ciò che pensi giusto e ciò che fai.',
  ],
  'letture|55|futuro': [
    'Mebahiah ti suggerisce di puntare su ciò che trasmetti agli altri con i tuoi gesti.',
  ],
  'letture|55|esito': [
    'Mebahiah ti invita a dirti parole che consolano, non che condannano, mentre aspetti.',
  ],
  'letture|55|altrui': [
    'Mebahiah vuole che tu viva nei gesti ciò che consideri giusto in un legame.',
  ],
  'letture|55|decisione': [
    'Mebahiah ti risponde sì se sai dire quale gesto quotidiano nasce da questa scelta; altrimenti aspetta.',
  ],
  'letture|55|scelta': [
    'Mebahiah favorisce quella che sapresti raccontare come esempio a chi ti è vicino.',
  ],
  'letture|55|come': [
    'Mebahiah ti esorta ad agire come ritieni giusto, con parole che rasserenano invece di ferire.',
  ],
  'letture|55|limite': [
    'Mebahiah ti consola con una parola buona, mentre fai con ordine la tua parte.',
  ],
  'letture|55|cuore_orienta': [
    'Mebahiah ti fa assaporare la pace di vivere come pensi.',
  ],
  'letture|55|cuore_attesa': [
    'Mebahiah ti offre il conforto di una parola buona.',
  ],
  'letture|55|cuore_legami': [
    'Mebahiah ti dà la calma di chi parla per rasserenare.',
  ],
  'letture|55|cuore_scelta': [
    'Mebahiah ti trasmette la fermezza serena del giusto.',
  ],
  'letture|55|cuore_limite': [
    'Mebahiah ti porta una consolazione semplice e quotidiana.',
  ],
  'letture|55|intelletto_orienta': [
    'Mebahiah ti ricorda che il giusto vive nei gesti.',
  ],
  'letture|55|intelletto_attesa': [
    'Mebahiah ti spiega che l\'attesa non sospende i gesti giusti.',
  ],
  'letture|55|intelletto_legami': [
    'Mebahiah ti avverte che si trasmette ciò che si fa.',
  ],
  'letture|55|intelletto_scelta': [
    'Mebahiah separa per te i proclami dai gesti.',
  ],
  'letture|55|intelletto_limite': [
    'Mebahiah ti rende chiaro che i piccoli gesti giusti contano.',
  ],
  'letture|55|gesto_orienta': [
    'Trasforma oggi un principio in cui credi in un tuo gesto concreto verso qualcuno.',
  ],
  'letture|55|gesto_attesa': [
    'Fai ogni giorno della settimana una piccola cosa giusta per ciò che aspetti, senza attendere l\'esito.',
  ],
  'letture|55|gesto_legami': [
    'Di\' oggi una parola che consola a chi ti è vicino, con semplicità e senza chiedere nulla.',
  ],
  'letture|55|gesto_scelta': [
    'Scrivi in una riga ciò che ritieni giusto e chiediti quale strada lo rende un gesto quotidiano.',
  ],
  'letture|55|gesto_limite': [
    'Scrivi una frase buona da rileggere nei momenti duri e tienila accanto alle domande per chi ti segue.',
  ],
  'letture|56|aperta': [
    'Poyel guarda con te a ciò che ti serve davvero, da chiedere senza sminuirlo.',
  ],
  'letture|56|futuro': [
    'Poyel ti fa puntare sul necessario, su ciò che ti serve per stare in piedi.',
  ],
  'letture|56|esito': [
    'Poyel ti chiede, mentre aspetti, di curare il necessario e lasciar perdere il superfluo.',
  ],
  'letture|56|altrui': [
    'Poyel ti aiuta a nominare in te ciò che ti serve dal legame, senza vergognartene.',
  ],
  'letture|56|decisione': [
    'Poyel dice sì se la scelta ti dà ciò che ti serve; se insegui il di più, aspetta.',
  ],
  'letture|56|scelta': [
    'Poyel sceglie con te la strada che ti serve, non quella che promette di più.',
  ],
  'letture|56|come': [
    'Poyel ti indica di chiedere una sola cosa chiara, senza sminuire quanto conta per te.',
  ],
  'letture|56|limite': [
    'Poyel ti accompagna nel chiedere ciò che ti serve sapere, senza scusarti di chiederlo.',
  ],
  'letture|56|cuore_orienta': [
    'Poyel ti rasserena col sapere quanto basta davvero.',
  ],
  'letture|56|cuore_attesa': [
    'Poyel ti dà la calma di non pretendere tutto subito.',
  ],
  'letture|56|cuore_legami': [
    'Poyel ti lascia sentire che anche un bisogno piccolo conta.',
  ],
  'letture|56|cuore_scelta': [
    'Poyel ti dà la leggerezza di volere il necessario.',
  ],
  'letture|56|cuore_limite': [
    'Poyel ti porta la dignità di chi chiede senza vergogna.',
  ],
  'letture|56|intelletto_orienta': [
    'Poyel ti insegna che chiedere poco non è valere poco.',
  ],
  'letture|56|intelletto_attesa': [
    'Poyel distingue per te il necessario da ciò che speri.',
  ],
  'letture|56|intelletto_legami': [
    'Poyel ti assicura che un bisogno detto piano resta intero.',
  ],
  'letture|56|intelletto_scelta': [
    'Poyel ti fa vedere la differenza fra necessario e superfluo.',
  ],
  'letture|56|intelletto_limite': [
    'Poyel ti ricorda che una domanda piccola merita risposta intera.',
  ],
  'letture|56|gesto_orienta': [
    'Scrivi la cosa che ti serve davvero questa settimana e chiedila a chi può darla, senza scusarti.',
  ],
  'letture|56|gesto_attesa': [
    'Fai l\'elenco di ciò che ti serve mentre aspetti e togli tutto ciò che è superfluo.',
  ],
  'letture|56|gesto_legami': [
    'Metti per iscritto, in una frase semplice, ciò che ti serve davvero da questo legame, senza sminuirlo.',
  ],
  'letture|56|gesto_scelta': [
    'Scrivi che cosa ti serve davvero e guarda, con calma, quale strada te lo dà senza chiederti troppo.',
  ],
  'letture|56|gesto_limite': [
    'Raccogli le domande che ti sembrano troppo piccole per farle e portale tutte a chi ti segue.',
  ],
  'letture|57|aperta': [
    'Nemamiah oggi ti porta a guardare la sostanza delle cose, non la loro apparenza.',
  ],
  'letture|57|futuro': [
    'Nemamiah ti indirizza su ciò che ha sostanza adesso, non su ciò che soltanto appare.',
  ],
  'letture|57|esito': [
    'Nemamiah ti chiede di curare la sostanza mentre aspetti, senza farti guidare dalle apparenze.',
  ],
  'letture|57|altrui': [
    'Nemamiah ti aiuta a separare in te la sostanza di questo legame dalle sue apparenze.',
  ],
  'letture|57|decisione': [
    'Nemamiah ti dà il sì se oltre l\'apparenza la sostanza regge; se ti attira soltanto la facciata, no.',
  ],
  'letture|57|scelta': [
    'Nemamiah ti fa scegliere quella che ha più sostanza, anche se l\'altra si presenta meglio.',
  ],
  'letture|57|come': [
    'Nemamiah ti porta alla sostanza: dire e fare ciò che conta, oltre le forme.',
  ],
  'letture|57|limite': [
    'Nemamiah ti aiuta a separare la sostanza dalle voci e a portare domande precise.',
  ],
  'letture|57|cuore_orienta': [
    'Nemamiah accende in te la fermezza di chi cerca sostanza.',
  ],
  'letture|57|cuore_attesa': [
    'Nemamiah ti dà una calma che le apparenze non scuotono.',
  ],
  'letture|57|cuore_legami': [
    'Nemamiah ti dà la pace di guardare la sostanza.',
  ],
  'letture|57|cuore_scelta': [
    'Nemamiah ti infonde la prontezza di chi ha capito.',
  ],
  'letture|57|cuore_limite': [
    'Nemamiah ti lascia la lucidità che le voci non confondono.',
  ],
  'letture|57|intelletto_orienta': [
    'Nemamiah distingue per te la sostanza da ciò che appare.',
  ],
  'letture|57|intelletto_attesa': [
    'Nemamiah ti fa capire che le apparenze non anticipano l\'esito.',
  ],
  'letture|57|intelletto_legami': [
    'Nemamiah ti ricorda che i modi non sono sostanza.',
  ],
  'letture|57|intelletto_scelta': [
    'Nemamiah ti mostra che una scelta si giudica dalla sostanza.',
  ],
  'letture|57|intelletto_limite': [
    'Nemamiah ti chiarisce che una voce non è una risposta.',
  ],
  'letture|57|gesto_orienta': [
    'Prendi una cosa che oggi ti occupa la mente e separa per iscritto la sostanza dall\'apparenza.',
  ],
  'letture|57|gesto_attesa': [
    'Scrivi che cosa c\'è di concreto in ciò che aspetti e che cosa è soltanto apparenza.',
  ],
  'letture|57|gesto_legami': [
    'Ripensa agli ultimi gesti di questo rapporto e annota per te quali hanno sostanza, al di là delle parole.',
  ],
  'letture|57|gesto_scelta': [
    'Per ciascuna strada scrivi che cosa resta tolta l\'apparenza, poi rileggilo con calma nei giorni seguenti.',
  ],
  'letture|57|gesto_limite': [
    'Separa ciò che hai sentito dire da ciò che sai davvero, poi porta i dubbi a chi è competente.',
  ],
  'letture|58|aperta': [
    'Ieialel ti orienta a restare su una cosa finché non ne capisci la causa.',
  ],
  'letture|58|futuro': [
    'Ieialel ti affida la tenacia: restare sulle cose finché le capisci.',
  ],
  'letture|58|esito': [
    'Ieialel ti sostiene nella fatica lunga, nel tornare su ciò che ancora non capisci.',
  ],
  'letture|58|altrui': [
    'Ieialel ti chiede di guardare la causa di ciò che senti, prima di concludere.',
  ],
  'letture|58|decisione': [
    'Ieialel ti risponde sì se hai guardato la cosa fino alle sue ragioni; se no, aspetta.',
  ],
  'letture|58|scelta': [
    'Ieialel ti porta verso quella di cui conosci le ragioni fino in fondo.',
  ],
  'letture|58|come': [
    'Ieialel ti porta a cercare la causa che sta sotto, oltre ogni singolo episodio.',
  ],
  'letture|58|limite': [
    'Ieialel resta con te nella fatica: tenere il filo, annotare, capire ciò che ti spiegano.',
  ],
  'letture|58|cuore_orienta': [
    'Ieialel ti infonde la forza quieta di chi non molla.',
  ],
  'letture|58|cuore_attesa': [
    'Ieialel ti porta la resistenza calma della fatica lunga.',
  ],
  'letture|58|cuore_legami': [
    'Ieialel nutre in te il desiderio tenace di capire davvero.',
  ],
  'letture|58|cuore_scelta': [
    'Ieialel ti porta la fiducia di chi guarda a fondo.',
  ],
  'letture|58|cuore_limite': [
    'Ieialel ti dà la tenuta di chi regge la fatica.',
  ],
  'letture|58|intelletto_orienta': [
    'Ieialel ti dimostra che ogni effetto ha una causa comprensibile.',
  ],
  'letture|58|intelletto_attesa': [
    'Ieialel ti insegna che tornare sulle cose le rende chiare.',
  ],
  'letture|58|intelletto_legami': [
    'Ieialel ti spiega che ogni reazione ha una causa.',
  ],
  'letture|58|intelletto_scelta': [
    'Ieialel separa per te la causa dalla semplice impressione.',
  ],
  'letture|58|intelletto_limite': [
    'Ieialel ti avverte che comprendere fino in fondo richiede tempo.',
  ],
  'letture|58|gesto_orienta': [
    'Fermati su una cosa che non ti torna e chiediti perché, poi ancora perché, finché arrivi alla causa.',
  ],
  'letture|58|gesto_attesa': [
    'Torna ogni giorno, per qualche minuto, su ciò che ancora non ti è chiaro e annota un passo avanti.',
  ],
  'letture|58|gesto_legami': [
    'Scrivi la tua reazione più frequente in questo rapporto e cerca, con calma, da dove nasce in te.',
  ],
  'letture|58|gesto_scelta': [
    'Per ogni strada scrivi le ragioni vere, poi chiediti perché per ciascuna; ripeti nei giorni seguenti senza fretta.',
  ],
  'letture|58|gesto_limite': [
    'Tieni un quaderno con ciò che ti spiegano e segna le domande rimaste aperte per il prossimo incontro.',
  ],
  'letture|59|aperta': [
    'Harahel ti indica oggi il valore di ciò che hai già, da apprezzare senza svalutarlo.',
  ],
  'letture|59|futuro': [
    'Harahel ti invita a puntare su ciò che sai, dandogli il valore che ha davvero.',
  ],
  'letture|59|esito': [
